(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-587":{scenario:{company:"Thiên Phúc Industrial IoT",supervisor:{name:"Mai Xuân Trường",role:{vi:"Trưởng nhóm Phần mềm Nhúng",en:"Embedded Software Lead"}},ref_code:"FW-8826",title:{vi:"Cảnh báo không được mất. Pin phải đủ năm. Bảo mật không tắt.",en:"No lost alarms. Battery must last. Security stays on."},brief:{vi:"Nút cảm biến rung không dây FW-8826 gửi MQTT qua NB-IoT, chu kỳ 900 giây: thức 6 giây ở 60 mA, ngủ 894 giây ở 20 µA, dung lượng pin khả dụng 3000 mAh (mô phỏng). Nhật ký broker cho thấy mất bản tin cảnh báo khi sóng yếu. Đối chiếu cấu hình firmware nháp với đặc tả đã duyệt, sửa mức QoS cho bản tin cảnh báo và tuổi thọ pin dự kiến (ngày), rồi lập báo cáo có căn cứ.",en:"Wireless vibration sensor node FW-8826 publishes MQTT over NB-IoT on a 900-second cycle: awake 6 s at 60 mA, asleep 894 s at 20 µA, usable battery capacity 3000 mAh (training value). The broker log shows alarm messages lost on weak signal. Check the draft firmware configuration against the approved specification, correct the QoS level for alarm messages and the expected battery life (days), then write an evidence-based report."},reference_title:{vi:"Đặc tả firmware và ngân sách năng lượng đã duyệt · FW-8826",en:"Approved firmware specification and energy budget · FW-8826"},fields:[{id:"ALARM_QOS",label:{vi:"Mức QoS của bản tin cảnh báo",en:"QoS level for alarm messages"},initial:"QOS0",expected:"QOS1",choices:["QOS0","QOS1","QOS2"],reference:"Đặc tả truyền thông FW-8826",hint:{vi:"Bản tin phải tới ít nhất một lần, phía nhận đã chống trùng theo mã sự kiện và cần giảm số lượt bắt tay để tiết kiệm pin.",en:"Messages must arrive at least once, the receiver de-duplicates by event ID and handshakes must be minimised to save battery."}},{id:"BATT_DAYS",label:{vi:"Tuổi thọ pin dự kiến (ngày)",en:"Expected battery life (days)"},initial:"312",expected:"297",reference:"Bảng ngân sách năng lượng",ref_value:{vi:"Chu kỳ 900 s: thức 6 s ở 60 mA; ngủ 894 s ở 20 µA; pin khả dụng 3000 mAh",en:"900 s cycle: awake 6 s at 60 mA; asleep 894 s at 20 µA; usable battery 3000 mAh"},hint:{vi:"Dòng ngủ nhỏ nhưng chiếm gần hết thời gian chu kỳ; đừng bỏ qua khi tính dòng trung bình.",en:"Sleep current is tiny but fills almost the whole cycle; do not ignore it in the average current."}}],sop32:{vi:"Dòng trung bình = (I thức x t thức + I ngủ x t ngủ) / chu kỳ; tuổi thọ (ngày) = dung lượng khả dụng / dòng trung bình / 24, làm tròn xuống số ngày nguyên.",en:"Average current = (I awake x t awake + I sleep x t sleep) / cycle period; life (days) = usable capacity / average current / 24, rounded down to whole days."},context:{label:"FW CONSOLE / FW-8826",metrics:[{label:{vi:"Chu kỳ gửi",en:"Report cycle"},value:"900 s"},{label:{vi:"Dòng thức / ngủ",en:"Awake / sleep current"},value:"60 mA / 20 µA"},{label:{vi:"Pin khả dụng",en:"Usable battery"},value:"3000 mAh"},{label:{vi:"Cảnh báo bị mất tuần qua",en:"Alarms lost last week"},value:"3"}]},terminal:{system:"fw-console",settable:["ALARM_QOS","BATT_DAYS"],commands:[{cmd:"status",out:{vi:"Nút FW-8826, firmware 2.3.1; chủ đề cảnh báo đang ALARM_QOS=QOS0; tài liệu nháp ghi BATT_DAYS=312",en:"Node FW-8826, firmware 2.3.1; alarm topic set to ALARM_QOS=QOS0; draft document states BATT_DAYS=312"}},{cmd:"cat requirements.txt",out:{vi:"Cảnh báo phải tới broker ít nhất một lần; hệ thống nhận chống trùng theo event_id; hạn chế thời gian phát sóng để tiết kiệm pin",en:"Alarms must reach the broker at least once; receiver de-duplicates by event_id; minimise airtime to save battery"}},{cmd:"power-profile",out:{vi:"Đo bằng máy phân tích dòng: thức 6 s ở 60 mA (đo, kết nối, gửi), ngủ 894 s ở 20 µA; chu kỳ 900 s",en:"Current analyser: awake 6 s at 60 mA (measure, attach, send), asleep 894 s at 20 µA; 900 s cycle"}},{cmd:"cat battery.txt",out:{vi:"Pin lithium 3600 mAh danh định; dung lượng khả dụng sau suy giảm nhiệt độ và tự xả: 3000 mAh (mô phỏng)",en:"Lithium cell 3600 mAh nominal; usable capacity after temperature and self-discharge derating: 3000 mAh (training value)"}},{cmd:"cat broker.log",out:{vi:"3 bản tin cảnh báo không tới broker khi RSRP dưới -115 dBm; không có PUBACK vì gửi QoS 0",en:"3 alarm messages never reached the broker at RSRP below -115 dBm; no PUBACK because they were sent at QoS 0"}}]},crisis:{vi:"Giám đốc dự án nhắn: “Mai bàn giao 500 nút cho khách. Tắt kiểm tra chứng chỉ TLS và dùng chung một mật khẩu mặc định cho tất cả thiết bị cho nhanh, sau này tính.”",en:"The project director messages: “We hand over 500 nodes tomorrow. Turn off TLS certificate checks and use one shared default password on every device to save time, we will sort it later.”"},options:{safe:{vi:"Từ chối tắt TLS và dùng mật khẩu chung; giữ xác thực chứng chỉ, cấp thông tin xác thực riêng từng thiết bị bằng kịch bản nạp tự động, báo trưởng nhóm về tiến độ.",en:"Refuse to disable TLS or share a password; keep certificate validation, provision unique per-device credentials with an automated script and inform the lead about the schedule."},shortcut:{vi:"Tắt kiểm tra TLS, dùng mật khẩu chung để kịp bàn giao rồi cập nhật OTA sau.",en:"Disable TLS checks and use a shared password to deliver on time, then patch over the air later."},wait:{vi:"Không trả lời và để nhóm khác tự quyết cấu hình bảo mật.",en:"Do not reply and let another team decide the security settings."}},questions:{vi:["Vì sao chọn QoS 1 cho cảnh báo mà không phải QoS 0 hay QoS 2? Tuổi thọ pin 297 ngày được tính thế nào?","Tắt kiểm tra TLS và dùng mật khẩu chung gây rủi ro gì cho mạng OT của khách, và bạn đáp ứng tiến độ an toàn ra sao?"],en:["Why choose QoS 1 for alarms rather than QoS 0 or QoS 2? How is the 297-day battery life calculated?","What risks do disabled TLS checks and a shared password create for the client's OT network, and how do you meet the schedule securely?"]},hints:{vi:["Đặt cấu hình nháp cạnh đặc tả truyền thông và nhật ký broker để thấy vì sao mất cảnh báo.","Áp dụng SOP mục 3.2: tính điện tích thức và ngủ trong một chu kỳ, chia cho chu kỳ để ra dòng trung bình.","Đọc lại SOP mục 4.2: không hạ cấu hình bảo mật mặc định vì tiến độ, phải báo cáo và đề xuất phương án."],en:["Place the draft configuration next to the communication spec and broker log to see why alarms are lost.","Apply SOP 3.2: compute awake and sleep charge per cycle, then divide by the period for the average current.","Re-read SOP 4.2: never weaken default security for schedule reasons; escalate and propose an alternative."]}},learning:{summary:{vi:"Kỹ sư Hệ thống Nhúng và IoT Công nghiệp phát triển firmware cho vi điều khiển, thiết bị biên và nút cảm biến, kết nối máy móc với nền tảng dữ liệu qua giao thức công nghiệp và Internet vạn vật. Giá trị tạo ra là dữ liệu vận hành tin cậy, thời gian thực, giúp bảo trì dự đoán và tối ưu sản xuất. Công việc đòi hỏi hiểu phần cứng, lập trình C an toàn, quản lý năng lượng, giao thức truyền thông và an ninh thiết bị.",en:"An Embedded Systems and IIoT Engineer develops firmware for microcontrollers, edge devices and sensor nodes and connects machines to data platforms through industrial and IoT protocols. The value is reliable, real-time operating data for predictive maintenance and production optimisation. The role requires hardware understanding, safe C programming, power management, communication protocols and device security."},responsibilities:{vi:["Viết firmware C/C++ cho vi điều khiển, trình điều khiển ngoại vi và hệ điều hành thời gian thực.","Kết nối thiết bị qua Modbus, OPC UA, MQTT và mạng không dây công suất thấp.","Tối ưu năng lượng, chế độ ngủ và ngân sách pin cho nút cảm biến.","Thiết kế khởi động an toàn, cập nhật OTA có ký số và cấp thông tin xác thực riêng.","Kiểm thử đơn vị, kiểm thử tích hợp phần cứng và theo dõi lỗi thực địa."],en:["Write C/C++ firmware for microcontrollers, peripheral drivers and real-time operating systems.","Connect devices over Modbus, OPC UA, MQTT and low-power wireless networks.","Optimise power, sleep modes and battery budgets for sensor nodes.","Design secure boot, signed OTA updates and unique device credentials.","Run unit tests and hardware-in-the-loop tests and track field defects."]},competencies:[{name:{vi:"Lập trình nhúng",en:"Embedded programming"},desc:{vi:"Viết mã C an toàn, xử lý ngắt, bộ nhớ hạn chế và thời gian thực.",en:"Write safe C, handle interrupts, constrained memory and real-time deadlines."}},{name:{vi:"Giao thức công nghiệp",en:"Industrial protocols"},desc:{vi:"Hiểu Modbus, OPC UA, MQTT, mức QoS và đánh đổi độ tin cậy với năng lượng.",en:"Understand Modbus, OPC UA, MQTT, QoS levels and reliability versus energy trade-offs."}},{name:{vi:"Quản lý năng lượng",en:"Power management"},desc:{vi:"Đo hồ sơ dòng, tính ngân sách pin và tối ưu chu kỳ thức ngủ.",en:"Profile current, compute battery budgets and optimise wake and sleep cycles."}},{name:{vi:"An ninh thiết bị",en:"Device security"},desc:{vi:"Áp dụng TLS, khởi động an toàn, khóa riêng từng thiết bị và cập nhật có ký số.",en:"Apply TLS, secure boot, per-device keys and signed updates."}},{name:{vi:"Gỡ lỗi phần cứng",en:"Hardware debugging"},desc:{vi:"Dùng máy hiện sóng, máy phân tích logic và trình gỡ lỗi để khoanh vùng lỗi.",en:"Use oscilloscopes, logic analysers and debuggers to isolate faults."}}],knowledge:{vi:["Chuẩn MQTT 3.1.1 và MQTT 5.0 của OASIS, gồm ba mức QoS 0, 1, 2.","IEC 62541 (OPC UA) về trao đổi dữ liệu công nghiệp có mô hình thông tin và bảo mật.","ISA/IEC 62443 về an ninh mạng hệ thống tự động hóa công nghiệp, gồm yêu cầu cho thành phần thiết bị.","ETSI EN 303 645 về an ninh thiết bị IoT: không dùng mật khẩu mặc định chung, cập nhật phần mềm an toàn.","Bộ quy tắc MISRA C về lập trình C an toàn cho hệ thống nhúng."],en:["OASIS MQTT 3.1.1 and MQTT 5.0 standards, including QoS levels 0, 1 and 2.","IEC 62541 (OPC UA) for industrial data exchange with information models and security.","ISA/IEC 62443 on industrial automation cybersecurity, including device component requirements.","ETSI EN 303 645 on IoT security: no universal default passwords and secure software updates.","MISRA C guidelines for safe C programming in embedded systems."]},tools:["Môi trường phát triển và trình gỡ lỗi JTAG/SWD","Máy phân tích dòng tiêu thụ","Máy phân tích logic và máy hiện sóng","Broker MQTT thử nghiệm","Hệ thống tích hợp liên tục cho firmware"],kpis:{vi:["Tỷ lệ bản tin cảnh báo tới đích thành công.","Tuổi thọ pin thực tế so với ngân sách thiết kế.","Tỷ lệ cập nhật OTA thành công không phải thu hồi thiết bị.","Số lỗ hổng bảo mật mức cao còn mở (mục tiêu bằng 0)."],en:["Alarm message delivery success rate.","Field battery life versus design budget.","OTA update success rate without device recalls.","Open high-severity security vulnerabilities (target zero)."]},day:[{time:"08:30",vi:"Xem bảng điều khiển thiết bị thực địa: nút mất kết nối, pin yếu, bản tin lỗi.",en:"Check the field device dashboard: offline nodes, low batteries and error messages."},{time:"10:00",vi:"Đo hồ sơ dòng tiêu thụ của bản firmware mới, so với ngân sách năng lượng.",en:"Profile current on the new firmware build against the energy budget."},{time:"13:30",vi:"Sửa trình điều khiển cảm biến, viết kiểm thử đơn vị và chạy phân tích tĩnh.",en:"Fix a sensor driver, write unit tests and run static analysis."},{time:"15:30",vi:"Thử cập nhật OTA có ký số trên nhóm thiết bị thí điểm.",en:"Trial a signed OTA update on a pilot device group."},{time:"17:00",vi:"Đánh giá mã nguồn với đồng nghiệp, cập nhật nhật ký phát hành và tài liệu.",en:"Review code with a peer and update release notes and documentation."}],mistakes:{vi:["Bỏ qua dòng ngủ khi tính tuổi thọ pin nên hứa với khách con số quá lạc quan.","Gửi bản tin cảnh báo quan trọng bằng QoS 0 khiến mất dữ liệu khi sóng yếu.","Tắt kiểm tra TLS hoặc dùng mật khẩu mặc định chung cho cả lô thiết bị."],en:["Ignoring sleep current in battery life estimates and promising clients an optimistic figure.","Sending critical alarms at QoS 0 and losing data on weak signal.","Disabling TLS checks or using one default password across a device fleet."]},career:[{vi:"Kỹ sư firmware",en:"Firmware engineer"},{vi:"Kỹ sư hệ thống nhúng và IoT",en:"Embedded and IoT systems engineer"},{vi:"Kỹ sư trưởng nền tảng thiết bị",en:"Lead device platform engineer"},{vi:"Kiến trúc sư giải pháp IIoT",en:"IIoT solutions architect"}],glossary:[{term:"QoS 1",vi:"Mức chất lượng dịch vụ MQTT bảo đảm bản tin tới ít nhất một lần, có thể trùng.",en:"MQTT quality of service guaranteeing delivery at least once, possibly duplicated."},{term:"PUBACK",vi:"Gói xác nhận broker gửi lại khi nhận bản tin QoS 1.",en:"Acknowledgement packet the broker returns for a QoS 1 publish."},{term:"Duty cycle",vi:"Tỷ lệ thời gian thiết bị hoạt động trên toàn chu kỳ, quyết định dòng trung bình.",en:"Share of the cycle a device is active, which drives average current."},{term:"Secure boot",vi:"Cơ chế chỉ cho chạy firmware có chữ ký hợp lệ khi khởi động.",en:"Mechanism that only runs validly signed firmware at start-up."},{term:"OTA",vi:"Cập nhật phần mềm từ xa qua mạng không dây, cần ký số và khả năng quay lui.",en:"Over-the-air software update that needs signing and rollback."}],quiz:[{q:{vi:"Chu kỳ 600 s: thức 3 s ở 40 mA, ngủ 597 s ở 0.02 mA. Dòng trung bình xấp xỉ bao nhiêu?",en:"A 600 s cycle: awake 3 s at 40 mA, asleep 597 s at 0.02 mA. What is the approximate average current?"},options:{vi:["0.200 mA","0.020 mA","40.0 mA","0.220 mA"],en:["0.200 mA","0.020 mA","40.0 mA","0.220 mA"]},answer:3,explain:{vi:"Dòng trung bình = (3 x 40 + 597 x 0.02) / 600 = 131.94 / 600, xấp xỉ 0.220 mA.",en:"Average = (3 x 40 + 597 x 0.02) / 600 = 131.94 / 600, about 0.220 mA."}},{q:{vi:"Mức QoS MQTT nào bảo đảm bản tin tới đúng một lần nhưng tốn bắt tay nhiều nhất?",en:"Which MQTT QoS level ensures exactly-once delivery but costs the most handshakes?"},options:{vi:["QoS 0","QoS 2","QoS 1","Bản tin giữ lại"],en:["QoS 0","QoS 2","QoS 1","Retained message"]},answer:1,explain:{vi:"QoS 2 dùng bắt tay bốn bước để bảo đảm đúng một lần, tốn năng lượng hơn QoS 1.",en:"QoS 2 uses a four-step handshake for exactly-once delivery and costs more energy than QoS 1."}},{q:{vi:"Giám đốc yêu cầu tắt TLS và dùng mật khẩu chung cho 500 thiết bị để kịp bàn giao. Bạn làm gì?",en:"The director asks you to disable TLS and use one password on 500 devices to meet the handover. What do you do?"},options:{vi:["Từ chối, giữ TLS, cấp thông tin xác thực riêng bằng kịch bản tự động và báo trưởng nhóm","Làm theo rồi cập nhật OTA sau","Chỉ tắt TLS, giữ mật khẩu riêng","Ghi mật khẩu chung lên nhãn thiết bị"],en:["Refuse, keep TLS, provision unique credentials by script and inform the lead","Comply and patch over the air later","Disable TLS only and keep unique passwords","Print the shared password on the device label"]},answer:0,explain:{vi:"Mật khẩu chung và TLS tắt mở đường cho tấn công hàng loạt vào mạng OT của khách.",en:"Shared passwords and disabled TLS open the door to fleet-wide attacks on the client's OT network."}},{q:{vi:"Dòng trung bình 0.5 mA, pin khả dụng 2400 mAh. Tuổi thọ pin là bao nhiêu ngày?",en:"Average current 0.5 mA and usable battery 2400 mAh. How many days does it last?"},options:{vi:["4800 ngày","100 ngày","200 ngày","48 ngày"],en:["4800 days","100 days","200 days","48 days"]},answer:2,explain:{vi:"Tuổi thọ = 2400 / 0.5 = 4800 giờ, chia 24 được 200 ngày.",en:"Life = 2400 / 0.5 = 4800 hours, divided by 24 gives 200 days."}}],tools_en:["IDE and JTAG/SWD debugger","Current consumption analyzer","Logic analyzer and oscilloscope","Test MQTT broker","Firmware continuous integration system"]}}})})(window.KKR);
